// GetActionType returns the ActionType CRD whose spec.name equals name, or
// (nil, nil) if none exists. Lookup is keyed by the business identifier
// (spec.name), not metadata.name -- mirrors AuthWebhook's existing
// findActionTypeKey convention (pkg/authwebhook/rw_reconciler.go).

func applyDependenciesToSpec(schema *models.WorkflowSchema, spec *rwv1alpha1.RemediationWorkflowSpec) {
	if schema.Dependencies == nil {
		return
	}
	deps := &rwv1alpha1.RemediationWorkflowDependencies{}
	for _, s := range schema.Dependencies.Secrets {
		deps.Secrets = append(deps.Secrets, rwv1alpha1.RemediationWorkflowResourceDependency{Name: s.Name})
	}
	for _, cm := range schema.Dependencies.ConfigMaps {
		deps.ConfigMaps = append(deps.ConfigMaps, rwv1alpha1.RemediationWorkflowResourceDependency{Name: cm.Name})
	}
	spec.Dependencies = deps
}

// are misleading for per-incident workflow selection. Ported verbatim from
// pkg/datastorage/server/workflow_discovery_handlers.go (Issue #1677 Phase 2d).
func convertWorkflowsToDiscoveryEntries(workflows []models.RemediationWorkflow) []models.WorkflowDiscoveryEntry {
	discoveryEntries := make([]models.WorkflowDiscoveryEntry, 0, len(workflows))
	for _, wf := range workflows {
		entry := models.WorkflowDiscoveryEntry{
			WorkflowID:      wf.WorkflowID,
			WorkflowName:    wf.WorkflowName,
			Name:            wf.Name,
			Description:     wf.Description,
			Version:         wf.Version,
			ExecutionEngine: string(wf.ExecutionEngine),
		}
		if wf.SchemaImage != nil {
			entry.SchemaImage = *wf.SchemaImage
		}
		if wf.ExecutionBundle != nil {
			entry.ExecutionBundle = *wf.ExecutionBundle
		}
		if wf.ServiceAccountName != nil {
			entry.ServiceAccountName = *wf.ServiceAccountName
		}
		discoveryEntries = append(discoveryEntries, entry)
	}
	return discoveryEntries
}

