// NewDiscoveredWorkflowState creates empty workflow-discovery state.
func NewDiscoveredWorkflowState() *DiscoveredWorkflowState {
	return &DiscoveredWorkflowState{workflowIDs: make(map[string]struct{})}
}

// Add records workflow IDs returned by list_workflows. Empty IDs are ignored.
func (s *DiscoveredWorkflowState) Add(workflowIDs ...string) {
	if s == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.workflowIDs == nil {
		s.workflowIDs = make(map[string]struct{})
	}
	for _, workflowID := range workflowIDs {
		if workflowID != "" {
			s.workflowIDs[workflowID] = struct{}{}
		}
	}
}

// Contains reports whether workflowID was returned by list_workflows.
func (s *DiscoveredWorkflowState) Contains(workflowID string) bool {
	if s == nil {
		return false
	}
	s.mu.RLock()
	defer s.mu.RUnlock()
	_, ok := s.workflowIDs[workflowID]
	return ok
}

// are misleading for per-incident workflow selection. Ported verbatim from
// pkg/datastorage/server/workflow_discovery_handlers.go (Issue #1677 Phase 2d).
func convertWorkflowsToDiscoveryEntries(workflows []models.RemediationWorkflow) []models.WorkflowDiscoveryEntry {
	discoveryEntries := make([]models.WorkflowDiscoveryEntry, 0, len(workflows))
	for _, wf := range workflows {
		entry := models.WorkflowDiscoveryEntry{
			WorkflowID:      wf.WorkflowID,
			WorkflowName:    wf.WorkflowName,
			Name:            wf.Name,
			Description:     wf.Description,
			Version:         wf.Version,
			ExecutionEngine: string(wf.ExecutionEngine),
		}
		if wf.SchemaImage != nil {
			entry.SchemaImage = *wf.SchemaImage
		}
		if wf.ExecutionBundle != nil {
			entry.ExecutionBundle = *wf.ExecutionBundle
		}
		if wf.ServiceAccountName != nil {
			entry.ServiceAccountName = *wf.ServiceAccountName
		}
		discoveryEntries = append(discoveryEntries, entry)
	}
	return discoveryEntries
}

